// CREDIT: http://www.aclockworkberry.com/shader-derivative-functions/

function flatFacesShader(p) {
	let canvas;
  let shader;
	let buffer;

  p.setup = function() {
    canvas = p.createCanvas(1112, 834);
		buffer = p.createGraphics(p.width, p.height, p.WEBGL);
		buffer.drawingContext.getExtension('OES_standard_derivatives');
		shader = buffer.createShader(vert, frag);
    buffer.noStroke();
		buffer.shader(shader);
  };

  p.draw = function() {
    p.background('white');

		buffer.clear();
		buffer.push();
		buffer.rotateY((p.millis() / 1000) * (p.PI / 4));

		buffer.ellipsoid(320, 320, 160);
		buffer.pop();

		p.image(buffer, 0, 0, p.width, p.height);
  };
}

let sketch = new p5(flatFacesShader);




// === Tab: vert.glsl.js ===
let vert = `

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
uniform mat3 uNormalMatrix;

attribute vec3 aPosition;    // Vertex position
// attribute vec2 aTexCoord;    // Vertex texture coordinate
attribute vec3 aNormal;      // Vertex normal
// attribute vec4 aVertexColor; // Vertex color

varying vec3 pos;
varying vec3 normalInterp;

void main(){
    gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
    vec4 pos4 = uModelViewMatrix * vec4(aPosition, 1.0);

    normalInterp = uNormalMatrix * aNormal;
    pos = vec3(pos4) / pos4.w;
}
`;

// === Tab: frag.glsl.js ===
let frag = `
#extension GL_OES_standard_derivatives : enable

precision mediump float;

varying vec3 pos;
varying vec3 normalInterp;

// This shader uses its own static lighting and coloring
// If you want to use p5js lighting/coloring see:
// https://github.com/processing/p5.js/blob/main/src/webgl/shaders/lighting.glsl
// and
// https://github.com/processing/p5.js/blob/main/src/webgl/shaders/phong.frag
const vec3 lightPos = vec3(200,60,100);
const vec3 ambientColor = vec3(0.0, 0.2, 0.0);
const vec3 diffuseColor = vec3(0.0, 0.5, 0.0);
const vec3 specColor = vec3(1.0, 1.0, 1.0);

void main() {
	// vec3 normal = normalize(normalInterp);
	vec3 normal = normalize(cross(dFdy(pos), dFdx(pos)));
	vec3 lightDir = normalize(lightPos - pos);

	float lambertian = max(dot(lightDir,normal), 0.0);
	float specular = 0.0;

	if(lambertian > 0.0) {
		vec3 viewDir = normalize(-pos);
		vec3 halfDir = normalize(lightDir + viewDir);
		float specAngle = max(dot(halfDir, normal), 0.0);
		specular = pow(specAngle, 16.0);
	}

	gl_FragColor = vec4(ambientColor + lambertian * diffuseColor + specular * specColor, 1.0);
}
`;

